/* Figma DNA — white canvas, five-color primary system, crisp 8px grid */
.theme-figma-dna {
  --bg: oklch(1 0 0);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.965 0 0);
  --fg: oklch(0.18 0 0);
  --fg-muted: oklch(0.55 0 0);
  --accent: oklch(0.670 0.183 249.2);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.591 0.244 291.7);
  --line: oklch(0.9 0 0);
  --success: oklch(0.742 0.182 153.0);
  --warning: oklch(0.714 0.186 41.3);
  --danger: oklch(0.652 0.234 26.7);

  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 0 0 1px oklch(0 0 0 / 8%);
  --shadow-2: 0 2px 8px oklch(0 0 0 / 12%), 0 0 0 1px oklch(0 0 0 / 6%);
  --shadow-3: 0 12px 32px -8px oklch(0 0 0 / 22%);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Instrument Sans", "Inter", sans-serif;
  --font-body: "Instrument Sans", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: none;
  --label-tracking: 0.005em;

  background-color: var(--bg);
  background-image:
    linear-gradient(oklch(0 0 0 / 3.5%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0 0 0 / 3.5%) 1px, transparent 1px);
  background-size: 8px 8px;
  color: var(--fg);
  font-family: var(--font-body);
  font-size: 0.875rem;
}

.theme-figma-dna h1,
.theme-figma-dna h2,
.theme-figma-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
}

/* Five-color primary system rotated across repeated blocks */
.theme-figma-dna li:nth-child(5n + 1) svg {
  color: oklch(0.62 0.22 25);
}
.theme-figma-dna li:nth-child(5n + 2) svg {
  color: oklch(0.72 0.17 55);
}
.theme-figma-dna li:nth-child(5n + 3) svg {
  color: oklch(0.55 0.2 295);
}
.theme-figma-dna li:nth-child(5n + 4) svg {
  color: oklch(0.65 0.17 150);
}
.theme-figma-dna li:nth-child(5n + 5) svg {
  color: oklch(0.6 0.19 250);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
